package kw.urtv.home;
import android.app.*;import android.content.*;import android.content.pm.ResolveInfo;import android.os.Bundle;import android.provider.Settings;import android.view.KeyEvent;import java.util.*;import kw.urtv.shared.TvPage;
public class RemoteSettingsActivity extends TvPage {
 private boolean capture; static volatile boolean editing;
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("remote_buttons",0);}
 static boolean allowed(int key){return (key>=KeyEvent.KEYCODE_BUTTON_A&&key<=KeyEvent.KEYCODE_BUTTON_MODE)||(key>=KeyEvent.KEYCODE_BUTTON_1&&key<=KeyEvent.KEYCODE_BUTTON_16)||(key>=KeyEvent.KEYCODE_PROG_RED&&key<=KeyEvent.KEYCODE_PROG_BLUE)||key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE||key==KeyEvent.KEYCODE_MEDIA_PLAY||key==KeyEvent.KEYCODE_MEDIA_PAUSE;}
 @Override public void onCreate(Bundle b){super.onCreate(b);render();}
 @Override protected void onResume(){super.onResume();editing=true;render();}
 @Override protected void onPause(){editing=false;super.onPause();}
 private void render(){title("أزرار الريموت","الأزرار الأصلية هي الافتراضية");addButton("إضافة زر",()->{capture=true;title("اضغط الزر المطلوب","اضغط رجوع للإلغاء · التنقل والصوت والطاقة محمية");note("بعض أزرار الشركات لا تصل إلى التطبيقات ولا يمكن تخصيصها هنا.");});for(Map.Entry<String,?> e:prefs(this).getAll().entrySet())if(e.getKey().startsWith("key_")){final String key=e.getKey(),pkg=String.valueOf(e.getValue());String label=pkg;try{label=getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(pkg,0)).toString();}catch(Exception ignored){}addButton(KeyEvent.keyCodeToString(Integer.parseInt(key.substring(4))).replace("KEYCODE_","")+" ← "+label,()->new AlertDialog.Builder(this).setTitle("حذف تعيين الزر؟").setPositiveButton("حذف",(d,n)->{prefs(this).edit().remove(key).apply();render();}).setNegativeButton("رجوع",null).show());}
 String enabled=Settings.Secure.getString(getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);boolean active=enabled!=null&&enabled.contains(getPackageName()+"/");note(active?"خدمة الأزرار مفعّلة من Android":"خدمة الأزرار متوقفة؛ لا تغيير خارج هذه الشاشة");addButton("فتح صلاحية الأزرار في Android",()->new AlertDialog.Builder(this).setTitle("تفعيل اختياري").setMessage("لتشغيل التعيينات أثناء المشاهدة، فعّل خدمة أزرار الريموت. تبقى الخدمة مرتبطة بالنظام ما دامت مفعّلة، ولا تقرأ محتوى الشاشة.").setPositiveButton("فتح الإعدادات",(d,n)->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))).setNegativeButton("رجوع",null).show());addButton("استعادة الأزرار الأصلية",()->{prefs(this).edit().clear().apply();RemoteButtonService.disable(this);render();});addButton("رجوع",this::finish);list.getChildAt(2).requestFocus();}
 @Override public boolean dispatchKeyEvent(KeyEvent e){if(!capture)return super.dispatchKeyEvent(e);if(e.getKeyCode()==KeyEvent.KEYCODE_BACK){if(e.getAction()==KeyEvent.ACTION_UP){capture=false;render();}return true;}if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){if(!allowed(e.getKeyCode())){android.widget.Toast.makeText(this,"هذا الزر محمي أو غير قابل للتخصيص",android.widget.Toast.LENGTH_SHORT).show();return true;}capture=false;choose(e.getKeyCode());}return true;}
 private void choose(int key){List<ResolveInfo> apps=Dock.catalogue(this,true);if(apps.isEmpty()){render();return;}String[] names=new String[apps.size()];for(int i=0;i<names.length;i++)names[i]=apps.get(i).loadLabel(getPackageManager()).toString();new AlertDialog.Builder(this).setTitle("اختر التطبيق").setItems(names,(d,n)->{prefs(this).edit().putString("key_"+key,apps.get(n).activityInfo.packageName).apply();render();}).setOnCancelListener(d->render()).show();}
 @Override public void onBackPressed(){if(capture){capture=false;render();}else super.onBackPressed();}
}
